function loopRunSum(nums: number[]): number {
  const n = nums.length;
  let best = -Infinity;
  for (let s = 0; s < n; s++) {
    let sum = 0;
    for (let len = 0; len < n; len++) {
      sum += nums[(s + len) % n];
      best = Math.max(best, sum);
    }
  }
  return best;
}

